import{_ as o,o as r,c as e,ah as n}from"./chunks/framework.DjU4PSOm.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"마음과 행동은 어떻게 관련되는가","slug":"마음과-행동은-어떻게-관련되는가","link":"#마음과-행동은-어떻게-관련되는가","children":[]},{"level":2,"title":"비트겐슈타인의 딱정벌레 논증","slug":"비트겐슈타인의-딱정벌레-논증","link":"#비트겐슈타인의-딱정벌레-논증","children":[]},{"level":2,"title":"헴펠의 의미 검증주의와 심리학적 진술의 번역","slug":"헴펠의-의미-검증주의와-심리학적-진술의-번역","link":"#헴펠의-의미-검증주의와-심리학적-진술의-번역","children":[]},{"level":2,"title":"헴펠 분석의 문제점","slug":"헴펠-분석의-문제점","link":"#헴펠-분석의-문제점","children":[]},{"level":2,"title":"믿음과 욕구 — 순환성 문제","slug":"믿음과-욕구-—-순환성-문제","link":"#믿음과-욕구-—-순환성-문제","children":[]},{"level":2,"title":"행동주의의 유산","slug":"행동주의의-유산","link":"#행동주의의-유산","children":[]}],"relativePath":"philosophy/Philosophy-of-Mind/03. 행동주의.md","filePath":"philosophy/Philosophy-of-Mind/03. 행동주의.md"}'),a={name:"philosophy/Philosophy-of-Mind/03. 행동주의.md"};function l(u,t,i,s,q,p){return r(),e("div",null,[...t[0]||(t[0]=[n('<h2 id="마음과-행동은-어떻게-관련되는가" tabindex="-1">마음과 행동은 어떻게 관련되는가 <a class="header-anchor" href="#마음과-행동은-어떻게-관련되는가" aria-label="Permalink to &quot;마음과 행동은 어떻게 관련되는가&quot;">​</a></h2><p>지금까지 심신 문제의 주된 플레이어는 마음과 두뇌였다. 여기에 제3의 플레이어, <strong>행동</strong>이 등장한다. 마음 상태와 행동은 최소한 다음과 같이 느슨하게 연결된다 — 마음 상태는 행동을 <strong>야기(cause)</strong>하거나 <strong>표현(express)</strong>하고, 행동은 마음 상태에 대한 <strong>증거(evidence)</strong>가 된다. 하지만 많은 철학자들은 이보다 훨씬 더 밀접하고 본질적인 관계가 있다고 생각했고, 이 생각이 가장 극단적인 형태로 나타난 것이 <strong>행동주의(behaviorism)</strong>다.</p><p>행동주의는 두 갈래로 구분된다.</p><ul><li><strong>철학적 행동주의</strong>: 심신 문제에 대한 하나의 입장으로, 마음 상태는 (대략) 행동 패턴에 불과하다는 주장.</li><li><strong>방법론적 행동주의</strong>: 심리학에서 허용 가능한 증거는 관찰 가능한 행동 데이터에만 국한되어야 한다는 주장. 심리학을 &quot;행동과학(behavioral science)&quot;이라 부르는 관행에도 이 영향이 남아 있다.</li></ul><p>(철학적) 행동주의의 동기는 크게 둘이다 — ①데카르트적 이원론에 대한 반발, ②논리실증주의의 검증주의 의미론. 20세기 전후 심리학에 대한 두 상반된 태도를 대비해 보면 이 배경이 잘 드러난다. 윌리엄 제임스는 &quot;심리학은 정신적 삶의 과학&quot;이며 &quot;내성적 관찰(introspective observation)&quot;을 일차적으로 신뢰해야 한다고 본 반면, J. B. 왓슨은 &quot;심리학은 순전히 객관적인 자연과학의 실험적 분과이며, 그 이론적 목표는 행동의 예측과 통제&quot;라고 선언했다.</p><h2 id="비트겐슈타인의-딱정벌레-논증" tabindex="-1">비트겐슈타인의 딱정벌레 논증 <a class="header-anchor" href="#비트겐슈타인의-딱정벌레-논증" aria-label="Permalink to &quot;비트겐슈타인의 딱정벌레 논증&quot;">​</a></h2><p>행동주의의 철학적 동기 중 하나는 데카르트적 마음 그림에 대한 비판이다. 데카르트적 전통은 마음을 일종의 &quot;극장(<strong>Cartesian theater</strong>)&quot;처럼 그린다 — 정신적 사건들이 무대 위에 등장하고, 유일한 관객은 나 자신뿐이어서 무대 위의 일은 나에게만 투명하며 타인은 간접적으로만 알 수 있다는 그림이다. 이 그림에서 &quot;고통을 느낀다&quot;는 말은 내가 무대 위의 어떤 심리적 대상(mental object)과 연결되어 있음을 뜻하고, &quot;고통&quot;이라는 단어는 그 대상을 지칭한다.</p><p>비트겐슈타인은 <strong>딱정벌레(beetle) 논증</strong>으로 이 그림을 겨냥한다.</p><blockquote><p>&quot;모든 사람이 각자 상자 하나씩을 가지고 있고, 그 속에는 우리가 &#39;딱정벌레&#39;라고 부르는 것이 들어있다고 가정해 보자. 아무도 다른 사람의 상자 속을 들여다볼 수 없다. … 그러나 그럼에도 불구하고 만일 이 사람들의 &#39;딱정벌레&#39;라는 낱말이 어떤 사용을 가진다면 — 그렇다면 그것은 어떤 한 사물의 명칭으로서의 사용은 아닐 것이다. 상자 속의 사물은 그 언어놀이에 전혀 속하지 않는다. … 왜냐하면 그 상자는 비어 있을 수도 있기 때문이다.&quot;</p></blockquote><p>즉 각자의 상자 안에 무엇이 들어 있든(혹은 비어 있든) &quot;딱정벌레&quot;라는 말의 쓰임에는 아무런 차이가 없다면, 그 단어의 의미는 상자 속 내용물을 지칭하는 데 있지 않다는 것. 이를 논증으로 재구성하면:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>P1</td><td>&quot;고통&quot;이라는 단어를 통해 의사소통이 가능하다</td></tr><tr><td>P2</td><td>만일 &quot;고통&quot;이 각자의 마음 안에 있는 사밀한(private) 무언가를 지칭한다면, 그 단어를 통한 의사소통은 불가능할 것이다</td></tr><tr><td>C</td><td>따라서 &quot;고통&quot;이라는 단어의 기능은 사밀한 무언가를 지칭하는 것이 아니다</td></tr></tbody></table><p>여기서 &quot;내가 고통을 느낀다&quot;는 진술은 오히려 공적으로 관찰 가능한 것에 의해 의미가 부여되어야 한다는 결론이 시사된다.</p><h2 id="헴펠의-의미-검증주의와-심리학적-진술의-번역" tabindex="-1">헴펠의 의미 검증주의와 심리학적 진술의 번역 <a class="header-anchor" href="#헴펠의-의미-검증주의와-심리학적-진술의-번역" aria-label="Permalink to &quot;헴펠의 의미 검증주의와 심리학적 진술의 번역&quot;">​</a></h2><p><strong>논리실증주의(logical positivism)</strong>는 1930~40년대(특히 독일·오스트리아) 정점을 이룬 철학 운동으로, 검증 가능성을 의미 있음의 기준으로 삼는 <strong>의미 검증주의(verification theory of meaning)</strong>를 내세웠다 — 경험적 진술의 의미를 이루는 것은 그 <strong>검증 조건</strong>이며, 검증 불가능하면서 분석적이지도 않은 진술은 사이비 진술(&quot;난센스&quot;)이라는 것이다(A. J. 에이어, 『언어, 논리, 진리』 참고). 논리실증주의는 오늘날 인기 있는 입장은 아니지만 철학과 과학 전반에 큰 영향을 남겼다.</p><p><strong>칼 헴펠(Carl Hempel)</strong>은 이 검증주의를 심리학에 적용한다 — 모든 유의미한 심리학적 진술은 공적으로 관찰 가능한 상황에 대한 진술로 번역 가능해야 한다는 것. 그는 &quot;이 방의 온도는 21.4도다&quot;를 여러 온도계·검류계의 눈금에 대한 진술들의 연언으로 정의하는 것을 모델로 삼는다. 다만 이 모델부터도 의문이 남는다 — 세 조건들을 전혀 이해하지 못하는 사람도 &quot;온도&quot;라는 개념 자체는 이해할 수 있지 않은가?</p><p>헴펠은 &quot;폴이 치통을 앓는다&quot;는 진술을 다음과 같은 시험 문장들의 연언으로 분석한다.</p><p>(a) 폴은 울먹거리고 특정한 몸짓을 한다 / (b) &quot;문제가 뭐야?&quot;라는 질문에 폴은 &quot;치통이 있어&quot;라고 대답할 것이다 / (c) 조사하면 충치가 발견될 것이다 / (d) 폴의 혈압·소화과정·반응속도 등에 변화가 있다 / (e) 폴의 중추신경계에서 특정 과정이 나타난다 …</p><p>헴펠은 이로부터 &quot;고통&quot;이라는 용어를 전혀 포함하지 않는 진술로 내용 손실 없이 재번역할 수 있다고 주장하며, 나아가 심리학은 결국 물리학의 한 분과이고 심신 문제는 &quot;가짜 문제&quot;이며, 모든 과학은 원칙적으로 하나의 본성을 공유하는 <strong>통합 과학(unitary science)</strong>이라고 결론짓는다.</p><h2 id="헴펠-분석의-문제점" tabindex="-1">헴펠 분석의 문제점 <a class="header-anchor" href="#헴펠-분석의-문제점" aria-label="Permalink to &quot;헴펠 분석의 문제점&quot;">​</a></h2><p>이 분석이 &quot;고통&quot;의 <strong>의미</strong>를 이룬다는 주장으로 읽으면 여러 문제가 드러난다.</p><ul><li><strong>(d), (e)를 포함시킨 것</strong>은 이해하기 어렵다 — 전문가만 아는 생리적 사실이 &quot;고통&quot;이라는 일상어의 의미를 이룬다고 보기는 힘들다. (실제로 행동주의자들은 대개 이런 항목을 행동에 포함시키지 않는다.)</li><li><strong>(c)의 문제</strong>: 충치가 발견되지 않더라도 치통을 느끼는 것은 가능하다(<strong>환상통(phantom pain)</strong> 사례).</li><li><strong>(a)의 문제(행동 성향)</strong>: 고통을 겪는 사람이라고 반드시 그것이 행동으로 드러나야 하는가? 천성적으로, 혹은 훈련을 통해 참을성이 많은 사람이라면? 이런 경우에도 어떤 &quot;성향(disposition)&quot;은 있다고 해야 할 텐데, 그 성향에 호소하는 것 자체가 이미 내적 상태에 대한 언급을 피하려는 행동주의의 취지를 벗어난다.</li><li><strong>(b)의 문제(언어적 행동)</strong>: &quot;문제가 뭐야?&quot;에 &quot;치통이 있어&quot;라고 답하려면, 폴이 한국어를 이해하고 진실을 말하려는 <strong>의도</strong>를 가져야 한다. 이 조건을 넣어 &quot;폴이 한국어를 이해하고 진실을 말하기를 원한다면 …&quot;으로 고쳐도, 이 수정된 분석 자체가 &quot;이해한다&quot;, &quot;원한다&quot;는 심리적 용어를 이미 포함하고 있어 순환에 빠진다.</li></ul><p>헴펠은 두 가지 반론에 직접 대응한다. ①&quot;열등감에 수반되는 행동은 열등감의 징후일 뿐 내적 본성이 아니다&quot;는 반론에 대해, 헴펠은 내성적(&quot;이해&quot;) 심리학자조차 신체 반응 없이는 가설을 확증할 수 없다고 응수한다. ②&quot;정신병의 모든 증상을 보이지만 실제로는 정신병이 없는 사람&quot;이 개념적으로 가능하지 않냐는 반론에 대해, 헴펠은 그런 구분 자체가 애초에 무의미(논리적 모순)하다고 답한다 — 행동적으로 완전히 구분 불가능한 두 사람을 &quot;실제로는 다르다&quot;고 판정할 기준이 없기 때문.</p><h2 id="믿음과-욕구-—-순환성-문제" tabindex="-1">믿음과 욕구 — 순환성 문제 <a class="header-anchor" href="#믿음과-욕구-—-순환성-문제" aria-label="Permalink to &quot;믿음과 욕구 — 순환성 문제&quot;">​</a></h2><p><strong>믿음</strong>과 <strong>욕구</strong>는 인간의 <strong>합리적 행동(rational behavior)</strong>을 지배하는 두 핵심 요소로서 특히 중요하다. 둘 다 명제를 대상으로 갖는 <strong>명제적 태도(propositional attitude)</strong>의 대표적 사례다.</p><p>언어적 행동만으로 믿음을 정의해 보면(&quot;S는 p를 믿는다 =def S에게 &#39;p가 참이야?&#39;라고 물으면 S는 &#39;맞아&#39;라고 답할 것이다&quot;) 앞서와 같은 문제(언어 이해·진실 의도의 전제, 동물에 부적용)가 반복된다.</p><p>더 근본적인 문제는 <strong>믿음-욕구의 상호의존</strong>이다.</p><blockquote><p>자신의 방향으로 자동차가 달려온다고 믿는 사람은 그것을 피하는 행동을 한다.<br> 맥주를 마시기 원하는 사람은 앞에 있는 맥주를 들이키는 행동을 한다.</p></blockquote><p>이런 사례들은 다음 원리를 뒷받침한다.</p><ul><li>믿음은 적절한 욕구와 결합되지 않는 한 단독으로는 행동을 일으키지 않는다.</li><li>욕구는 적절한 믿음과 결합되지 않는 한 단독으로는 행동을 일으키지 않는다.</li></ul><p>(전자의 원리는 흔히 흄(Hume)에게 귀속된다 — &quot;이성은 정념의 노예다.&quot;) 이 원리가 참이라면, 행동만으로 &quot;믿음&quot;을 정의하려는 시도는 반드시 &quot;욕구&quot;라는 또 다른 마음 상태를 끌어들여야 하고, 욕구 역시 믿음을 끌어들여야 정의될 수 있다 — <strong>순환성(circularity)</strong>에 빠지는 것이다.</p><h2 id="행동주의의-유산" tabindex="-1">행동주의의 유산 <a class="header-anchor" href="#행동주의의-유산" aria-label="Permalink to &quot;행동주의의 유산&quot;">​</a></h2><p>헴펠에 대한 비판에서 드러난 두 문제는 행동주의 전반의 근본적 난점으로 여겨진다.</p><table tabindex="0"><thead><tr><th>문제</th><th>내용</th></tr></thead><tbody><tr><td>(A)</td><td>어떤 마음 상태에 있으면서도 아무 행동을 나타내지 않을 수 있다</td></tr><tr><td>(B)</td><td>대부분의 마음 상태는 다른 마음 상태와 결합해야만 행동으로 이어진다 → 행동적 정의는 순환에 빠지기 쉽다</td></tr></tbody></table><p>헴펠식의 극단적 행동주의를 오늘날 받아들이는 철학자는 거의 없다. 그럼에도 마음 상태와 행동 사이에 어떤 필연적·논리적 연결이 있다는 발상 자체는 여러 형태로 살아남았다. 남는 과제는 두 가지다 — (1) 마음 상태와 행동의 필연적 연결을 순환에 빠지지 않게 더 그럴듯하게 분석하는 것, (2) 그 순환성 문제를 어떻게 해결할 것인가. 이 문제의식은 이후 암스트롱과 <strong>기능주의</strong>로 이어진다.</p>',34)])])}const g=o(a,[["render",l]]);export{h as __pageData,g as default};
